package com.sanctuarygames.createtransit.radio.client;
import java.util.*;import com.sanctuarygames.createtransit.radio.*;import com.sanctuarygames.createtransit.elevator.ElevatorPackets;import com.sanctuarygames.createtransit.elevator.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.world.entity.player.Inventory;import net.minecraft.network.chat.Component;import net.neoforged.neoforge.network.PacketDistributor;
public final class SpeakerScreen extends AbstractContainerScreen<SpeakerMenu> {
 private final Map<AbstractWidget,Integer> widgets=new LinkedHashMap<>();private int scroll;private double scrollTarget;private long scrollTime;private boolean draggingScroll;private String signature="";
 public SpeakerScreen(SpeakerMenu m,Inventory i,Component t){super(m,i,t);imageWidth=360;imageHeight=304;}
 private void position(){scroll=ElevatorScreen.layoutWidgets(widgets,topPos,imageHeight,scroll,80);}
 @Override protected void init(){imageWidth=Math.min(400,width-12);imageHeight=Math.min(390,height-12);widgets.clear();clearWidgets();super.init();RadioControls.build(new RadioControls.Host(){
  public Button button(String s,int x,int y,int w,Button.OnPress action){var b=addRenderableWidget(StationUi.button(leftPos+x,topPos+y,w,20,s,action));widgets.put(b,y);return b;}
  public EditBox field(int x,int y,int w,String s,int max){var b=new EditBox(font,leftPos+x,topPos+y,w,18,com.sanctuarygames.createtransit.TransitText.uiText(s));b.setMaxLength(max);b.setValue(s);addRenderableWidget(b);widgets.put(b,y);return b;}
  public void send(int op,String key,String value){PacketDistributor.sendToServer(new ElevatorPackets.Action(menu.containerId,op,0,key,value,true,0,0,0));}
  public void slider(String label,int x,int y,int w,double v,java.util.function.DoubleConsumer save){var b=addRenderableWidget(StationUi.slider(leftPos+x,topPos+y,w,label,v,save));widgets.put(b,y);}
 },menu.state(),menu.state().getCompound("Radio"),82,imageWidth,true);position();addRenderableWidget(StationUi.button(leftPos+14,topPos+imageHeight-27,imageWidth-28,20,"Done",b->onClose()));signature=menu.state().toString();}
 @Override public boolean mouseScrolled(double x,double y,double h,double v){if(x<leftPos||x>leftPos+imageWidth||y<topPos+80||y>topPos+imageHeight-36)return super.mouseScrolled(x,y,h,v);scrollTarget=Math.clamp(scrollTarget-v*28,0,maxScroll());return true;}
 private void drag(double y){scrollTarget=Math.clamp((y-topPos-80)/(imageHeight-116.0),0,1)*maxScroll();scroll=(int)scrollTarget;position();}
 @Override public boolean mouseClicked(double x,double y,int button){if(button==0&&x>=leftPos+imageWidth-10&&x<=leftPos+imageWidth&&y>=topPos+80&&y<=topPos+imageHeight-36&&maxScroll()>0){draggingScroll=true;drag(y);return true;}return super.mouseClicked(x,y,button);}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(draggingScroll){drag(y);return true;}return super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean mouseReleased(double x,double y,int button){draggingScroll=false;return super.mouseReleased(x,y,button);}
 private int maxScroll(){return Math.max(0,widgets.values().stream().mapToInt(Integer::intValue).max().orElse(80)+20-(imageHeight-36));}
 @Override public boolean keyPressed(int key,int scan,int mods){if(key!=256&&getFocused() instanceof EditBox box&&box.isFocused()){box.keyPressed(key,scan,mods);return true;}return super.keyPressed(key,scan,mods);}
 @Override protected void containerTick(){super.containerTick();if(!signature.equals(menu.state().toString()))init();}
 @Override protected void renderBg(GuiGraphics g,float partial,int mx,int my){StationUi.panel(g,leftPos,topPos,imageWidth,imageHeight,0xff152433,0xff557b99);StationUi.panel(g,leftPos+8,topPos+76,imageWidth-16,imageHeight-112,0xff101f2c,0xff344f63);}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){if(maxScroll()>0){int span=imageHeight-116,thumb=Math.max(8,span*span/(span+maxScroll())),yy=80+(span-thumb)*scroll/Math.max(1,maxScroll());g.fill(imageWidth-7,80,imageWidth-4,imageHeight-36,0xff294355);g.fill(imageWidth-7,yy,imageWidth-4,yy+thumb,StationUi.accent());}g.drawString(font,com.sanctuarygames.createtransit.TransitText.ui("Station Speaker"),14,13,StationUi.INK,false);g.drawString(font,com.sanctuarygames.createtransit.TransitText.ui("CREATE: STATION UTILITIES"),14,29,StationUi.accent(),false);g.drawString(font,font.plainSubstrByWidth(RadioClient.status(),imageWidth-28),14,47,StationUi.MUTED,false);g.drawString(font,com.sanctuarygames.createtransit.TransitText.ui("Wall / ceiling • shared station list"),14,61,StationUi.MUTED,false);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){long now=System.nanoTime();double dt=scrollTime==0?.016:Math.min(.1,(now-scrollTime)/1e9);scrollTime=now;scrollTarget=Math.clamp(scrollTarget,0,maxScroll());double d=scrollTarget-scroll;scroll=Math.abs(d)<1?(int)Math.round(scrollTarget):(int)Math.round(scroll+Math.copySign(Math.max(1,Math.abs(d)*(1-Math.exp(-18*dt))),d));position();super.render(g,x,y,partial);renderTooltip(g,x,y);}
}
